CREATE TABLE IF NOT EXISTS location_local_seo (
  location_slug TEXT PRIMARY KEY,
  utility_name TEXT NOT NULL,
  permit_office TEXT NOT NULL,
  permit_note TEXT NOT NULL,
  property_context TEXT NOT NULL,
  parking_context TEXT NOT NULL,
  commercial_context TEXT NOT NULL,
  FOREIGN KEY (location_slug) REFERENCES location_pages(location_slug)
);

INSERT OR REPLACE INTO location_local_seo (
  location_slug,
  utility_name,
  permit_office,
